import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"键盘快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/reference/keyboard.md","filePath":"zh/kimi-code-cli/reference/keyboard.md"}`),a={name:`kimi-code-cli/reference/keyboard.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to “键盘快捷键”">​</a></h1><p>Kimi Code CLI 的 TUI 交互模式支持一套键盘快捷键。键位按使用场景分为五组：通用输入、模式切换、流式输出期间、工具输出控制、审批面板，以及弹窗浏览。在 TUI 中输入 <code>/help</code> 可随时打开内置快捷键清单。</p><h2 id="通用快捷键" tabindex="-1">通用快捷键 <a class="header-anchor" href="#通用快捷键" aria-label="Permalink to “通用快捷键”">​</a></h2><p>以下键位在输入框中始终可用：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>提交当前输入</td></tr><tr><td><code>Shift-Enter</code> / <code>Ctrl-J</code></td><td>在输入中插入换行</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>浏览输入历史</td></tr><tr><td><code>Esc</code></td><td>关闭弹窗 / 取消补全 / 中断流式输出或上下文压缩</td></tr><tr><td><code>Ctrl-C</code></td><td>中断当前流式输出，或清空输入框</td></tr><tr><td><code>Ctrl-D</code></td><td>在输入框为空时退出 Kimi Code CLI</td></tr><tr><td><code>Ctrl-T</code></td><td>待办列表被截断时，展开或折叠完整列表</td></tr></tbody></table><p><strong>流式输出期间</strong>按 <code>Ctrl-C</code> 会立即取消，无需二次确认。</p><p><strong>退出程序</strong>（输入框为空时按 <code>Ctrl-C</code>，或按 <code>Ctrl-D</code>）使用「双击确认」机制：第一次按下后状态栏会出现提示，再按一次相同的键才真正退出。中途按其他键会清除确认状态。</p><h2 id="模式切换" tabindex="-1">模式切换 <a class="header-anchor" href="#模式切换" aria-label="Permalink to “模式切换”">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Shift-Tab</code></td><td>切换 Plan 模式</td></tr><tr><td><code>!</code></td><td>在空输入框中进入 Shell 模式</td></tr></tbody></table><p>按 <code>Shift-Tab</code> 可开启或关闭 Plan 模式。开启后，Agent 会优先使用只读工具进行研究和规划，并可写入当前计划文件；<code>Bash</code> 按当前权限模式和普通规则处理，不会因 Plan 模式额外发起独立审批。单纯切换模式不会创建空计划文件。再次按 <code>Shift-Tab</code> 退出 Plan 模式。</p><p>在空输入框中键入 <code>!</code> 进入 Shell 模式，可直接运行终端命令；命令运行期间按 <code>Ctrl+B</code> 可将其转为后台任务。详见<a href="/code/docs/kimi-code-cli/guides/interaction.html#shell-模式">交互与输入</a>。</p><h2 id="输入与编辑" tabindex="-1">输入与编辑 <a class="header-anchor" href="#输入与编辑" aria-label="Permalink to “输入与编辑”">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl-G</code></td><td>在外部编辑器中编辑当前输入</td></tr><tr><td><code>Ctrl-V</code></td><td>粘贴剪贴板中的图片或视频（Unix / macOS）</td></tr><tr><td><code>Alt-V</code></td><td>粘贴剪贴板中的图片或视频（Windows）</td></tr><tr><td><code>Ctrl--</code></td><td>撤销（Undo）</td></tr><tr><td><code>Esc</code> <code>Esc</code></td><td>双击打开撤销选择框（空闲状态下）</td></tr></tbody></table><p>按 <code>Ctrl-G</code> 会打开外部编辑器，编辑器按以下优先级选择：</p><ol><li><code>/editor</code> 命令配置的编辑器</li><li><code>$VISUAL</code> 环境变量</li><li><code>$EDITOR</code> 环境变量</li></ol><p>保存并退出后，编辑内容替换输入框；不保存退出则保持原样。</p><p>粘贴图片或视频时，输入框中显示占位符，实际媒体数据在提交时一并发送给模型。优先从系统剪贴板读取；Linux 上会尝试 Wayland 与 X11，WSL 下还会通过 PowerShell 兜底读取 Windows 剪贴板。</p><h2 id="流式输出期间" tabindex="-1">流式输出期间 <a class="header-anchor" href="#流式输出期间" aria-label="Permalink to “流式输出期间”">​</a></h2><p>流式输出（streaming）期间，输入框依然可以接收输入，并支持以下额外操作：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl-S</code></td><td>Steer：将当前输入立即注入正在运行的轮次</td></tr><tr><td><code>Esc</code></td><td>中断当前流式输出</td></tr><tr><td><code>Ctrl-C</code></td><td>中断当前流式输出</td></tr></tbody></table><p>按 <code>Ctrl-S</code> 时，模型会在下一个可中断的时机立刻看到你的消息，无需等待当前轮次结束。</p><h2 id="工具输出" tabindex="-1">工具输出 <a class="header-anchor" href="#工具输出" aria-label="Permalink to “工具输出”">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl-O</code></td><td>展开或折叠工具输出和压缩摘要</td></tr></tbody></table><p>历史中存在折叠的工具调用结果时，按 <code>Ctrl-O</code> 可在折叠和展开之间切换。压缩完成后，同一个快捷键也会在压缩块中显示或隐藏压缩摘要。</p><h2 id="审批面板" tabindex="-1">审批面板 <a class="header-anchor" href="#审批面板" aria-label="Permalink to “审批面板”">​</a></h2><p>当 Agent 发起需要确认的工具调用时，TUI 会弹出审批面板。详细审批流程见<a href="/code/docs/kimi-code-cli/guides/interaction.html#审批流程">交互与输入</a>，面板内可用键位如下：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>在候选选项之间移动光标</td></tr><tr><td><code>Enter</code></td><td>确认当前选中的选项</td></tr><tr><td><code>1</code> ~ <code>9</code></td><td>直接选择对应序号的选项</td></tr><tr><td><code>Esc</code> / <code>Ctrl-C</code> / <code>Ctrl-D</code></td><td>拒绝当前请求</td></tr><tr><td><code>Ctrl-E</code></td><td>面板包含 diff 或文件内容预览时，展开或折叠完整内容</td></tr><tr><td><code>Ctrl-O</code></td><td>切换其他工具输出的折叠状态</td></tr></tbody></table><p>需要附带反馈的选项（如「Reject」「Revise」）会在确认后切换到反馈输入态：直接输入反馈文本，按 <code>Enter</code> 提交；按 <code>Esc</code> 退出反馈输入并回到候选列表。</p><h2 id="弹窗模式" tabindex="-1">弹窗模式 <a class="header-anchor" href="#弹窗模式" aria-label="Permalink to “弹窗模式”">​</a></h2><p>输入 <code>/help</code> 打开帮助面板后，可使用以下键位浏览和关闭面板：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>单行滚动</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>每次滚动 10 行</td></tr><tr><td><code>Esc</code> / <code>Enter</code> / <code>q</code> / <code>Q</code></td><td>关闭面板</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/reference/slash-commands.html">斜杠命令</a> — TUI 内置的控制命令速查</li><li><a href="/code/docs/kimi-code-cli/reference/kimi-command.html">kimi 命令</a> — 启动参数与子命令完整参考</li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};